pub fn jq_classify_observation(plan: Rc<JqAdmittedProcessPlan>, observation: Rc<ProcessObservation>) -> Rc<JqOutcome> {
    match plan.exit_policy() {
    JqExitPolicy::JqProgramExit => if (observation.exit_code.clone() != 0) {
        Rc::new(JqOutcome::JqExecutionRefused {
    exit_code: observation.exit_code.clone(),
    stderr: observation.stderr.clone(),
})
    } else {
        if (v1_rt::trim(observation.stdout.clone()) == "".to_string()) {
            Rc::new(JqOutcome::JqOutputAbsent)
        } else {
            Rc::new(JqOutcome::JqOutputPresent {
    text: observation.stdout.clone(),
})
        }
    },
    JqExitPolicy::JqLastResultExit => if (observation.exit_code.clone() == 4) {
        Rc::new(JqOutcome::JqOutputAbsent)
    } else {
        if ((observation.exit_code.clone() == 0) || (observation.exit_code.clone() == 1)) {
            if (v1_rt::trim(observation.stdout.clone()) == "".to_string()) {
                Rc::new(JqOutcome::JqOutputAbsent)
            } else {
                Rc::new(JqOutcome::JqOutputPresent {
    text: observation.stdout.clone(),
})
            }
        } else {
            Rc::new(JqOutcome::JqExecutionRefused {
    exit_code: observation.exit_code.clone(),
    stderr: observation.stderr.clone(),
})
        }
    },
}
}

pub fn jq_admitted_plan_surface(plan: Rc<JqAdmittedProcessPlan>) -> Rc<CliSurface> {
    plan.surface()
}

pub fn jq_admitted_plan_input(plan: Rc<JqAdmittedProcessPlan>) -> Rc<JqProcessInput> {
    plan.process_input()
}

pub fn jq_invocation_process_plan(invocation: Rc<JqInvocation>) -> Rc<Outcome<Rc<JqAdmittedProcessPlan>>> {
    match (*jq_invocation_lower(invocation.clone())).clone() {
    JqLowering::JqLoweringRefused { cause: cause, .. } => crate::v2_std_diagnostic::outcome_rejected(jq_lowering_refused_diagnostic(cause.clone())),
    JqLowering::JqLowered { plan: plan, .. } => crate::v2_std_diagnostic::bind_outcome(crate::v2_std_compilers_cli_surface::serialize_cli_arguments(plan.arguments.clone(), jq_cli_lex_rules(), plan.binding_spellings.clone()), |surface| crate::v2_std_diagnostic::outcome_accepted(Rc::new(JqAdmittedProcessPlan {
    surface: surface.clone(),
    process_input: plan.process_input.clone(),
    exit_policy: invocation.exit_policy.clone(),
}))),
}
}

pub fn jq_invocation_cli_arguments(invocation: Rc<JqInvocation>) -> Rc<Outcome<Rc<CliSurface>>> {
    match (*jq_invocation_lower(invocation)).clone() {
    JqLowering::JqLoweringRefused { cause: cause, .. } => crate::v2_std_diagnostic::outcome_rejected(jq_lowering_refused_diagnostic(cause.clone())),
    JqLowering::JqLowered { plan: plan, .. } => crate::v2_std_compilers_cli_surface::serialize_cli_arguments(plan.arguments.clone(), jq_cli_lex_rules(), plan.binding_spellings.clone()),
}
}

pub fn jq_lowering_refusal_identity(cause: JqLoweringRefusal) -> std::string::String {
    match cause.clone() {
    JqLoweringRefusal::JqBindingNameDuplicate => "jq_binding_name_duplicate".to_string(),
    JqLoweringRefusal::JqTextBindingUnwired => "jq_text_binding_unwired".to_string(),
}
}

pub fn jq_lowering_refused_diagnostic(cause: JqLoweringRefusal) -> Rc<Diagnostic> {
    Rc::new(Diagnostic {
    reason: jq_lowering_refusal_identity(cause),
    at: crate::v2_std_diagnostic::node_locus(Rc::new(Node {
    kind: Rc::new(NodeKind::TypeNode {
    connective: Rc::new(Connective::Atom {
    identity: "jq_invocation_lowering".to_string(),
}),
}),
    children: Rc::new(vec![]),
    occurrence_id: Rc::new(NodeOccurrenceIdentity::OccurrenceSynthetic),
})),
    correction: Rc::new(Correction::Unavailable {
    reason: Rc::new(NoCorrectionReason::ExternalContractUnknown),
}),
})
}

pub async fn jq_execute_admitted_plan(plan: Rc<JqAdmittedProcessPlan>, jq_process: &Jq__Process) -> std::result::Result<Rc<ProcessObservation>, std::boxed::Box<dyn std::error::Error>> {
    let arguments = crate::v2_std_compilers_cli_surface::process_argv_expansion(plan.surface());
Ok(match (*plan.process_input()).clone() {
    JqProcessInput::JqProcessStdin { content: payload, .. } => {
        let ran = jq_process.run_with_stdin(arguments.clone(), payload.clone()).await?;
crate::extdeps_shell_exec::process_observation(ran.0.clone(), ran.1.clone(), ran.2.clone())
},
    JqProcessInput::JqProcessNoStdin => {
        let ran = jq_process.run_without_stdin(arguments.clone()).await?;
crate::extdeps_shell_exec::process_observation(ran.0.clone(), ran.1.clone(), ran.2.clone())
},
})
}

pub async fn jq_argv_expansion_probe(expansion: Rc<ProcessArgvExpansion>, payload: String, jq_process: &Jq__Process) -> std::result::Result<i64, std::boxed::Box<dyn std::error::Error>> {
    Ok(jq_process.run_with_stdin(expansion.clone(), payload.clone()).await?.0.clone())
}

